column2:
for hashed_word in [seed, record.jsn, record.timeline as u64, record.previous_record_hash] {
    for byte in hashed_word.to_le_bytes() {
        hash_state ^= byte as u64;
        hash_state = hash_state.wrapping_mul(0x0000_0100_0000_01b3);
    }
}
// 终混（splitmix64 的形态）：把高位的差异搅进低位，否则截低位等于只看一条窄通道
hash_state ^= hash_state >> 33; hash_state = hash_state.wrapping_mul(0xff51_afd7_ed55_8ccd);
hash_state ^= hash_state >> 33; hash_state = hash_state.wrapping_mul(0xc4ce_b9fe_1a85_ec53);
hash_state ^= hash_state >> 33;

column3:
for hashed_word in [record.jsn, record.timeline as u64, record.previous_record_hash, seed] {
    for byte in hashed_word.to_le_bytes() {
        hash_state ^= byte as u64;
        hash_state = hash_state.wrapping_mul(0x0000_0100_0000_01b3);
    }
}
